{
  "title": "Internal Host Port Scan Detected",
  "id": "example-sigma-001",
  "status": "experimental",
  "description": "Detects internal hosts performing high‑volume TCP port scans indicative of reconnaissance activity.",
  "author": "SOC Team",
  "logsource": {
    "product": "firewall",
    "service": "network"
  },
  "detection": {
    "selection": {
      "event_type": "network_scan",
      "outcome": "blocked"
    },
    "condition": "selection",
    "timeframe": "60",
    "threshold": {
      "count": 100,
      "field": "dest_port"
    }
  },
  "fields": ["source_ip", "dest_ip", "dest_port", "timestamp"],
  "falsepositives": ["Authorized vulnerability assessments"],
  "level": "high"
}
